def translate(pat, sep=None):
    """Translate a shell PATTERN to a regular expression.

    A path separator character may be supplied to the *sep* argument. If
    given, '*' and '?' wildcards will not match separators; '*' wildcards in
    standalone pattern segments match precisely one path segment; and  '**'
    wildcards in standalone segments match any number of path segments.

    There is no way to quote meta-characters.
    """
    if sep:
        return _translate_full(pat, sep)
    return _translate(pat)


def _translate(pat):
    STAR = object()
    parts = _translate_parts(pat, STAR, '.')
    res = _join_translated_parts(parts, STAR)
    return fr'(?s:{res})\Z'


def _translate_full(pat, sep):
    SEP = re.escape(sep)
    DOT = f'[^{SEP}]'
    parts = _translate_parts(pat, None, DOT, sep=sep, escaped_sep=SEP)
    res = ''.join(parts)
    return fr'(?s:{res})\Z'


def _translate_parts(pat, star, question_mark, *, sep=None, escaped_sep=None):
    res = []
    add = res.append
    i, n = 0, len(pat)
    while i < n:
        c = pat[i]
        i = i+1
        if c == '*':
            # compress consecutive `*` into one
            h = i-1
            while i < n and pat[i] == '*':
                i = i+1
            if sep:
                star_count = i-h
                is_segment = (h == 0 or pat[h-1] == sep) and (i == n or pat[i] == sep)
                if star_count == 1:
                    if is_segment:
                        add(f'{question_mark}+')
                    else:
                        add(f'{question_mark}*')
                elif star_count == 2 and is_segment:
                    if i == n:
                        add('.*')
                    else:
                        add(f'(.*{escaped_sep})?')
                        i = i+1
                else:
                    raise ValueError("Invalid pattern: '**' can only be an entire path component")
            else:
                add(star)
        elif c == '?':
            add(question_mark)
        elif c == '[':
            j = i
            if j < n and pat[j] == '!':
                j = j+1
            if j < n and pat[j] == ']':
                j = j+1
            while j < n and pat[j] != ']':
                j = j+1
            if j >= n:
                add('\\[')
            else:
                stuff = pat[i:j]
                if '-' not in stuff:
                    stuff = stuff.replace('\\', r'\\')
                else:
                    chunks = []
                    k = i+2 if pat[i] == '!' else i+1
                    while True:
                        k = pat.find('-', k, j)
                        if k < 0:
                            break
                        chunks.append(pat[i:k])
                        i = k+1
                        k = k+3
                    chunk = pat[i:j]
                    if chunk:
                        chunks.append(chunk)
                    else:
                        chunks[-1] += '-'
                    # Remove empty ranges -- invalid in RE.
                    for k in range(len(chunks)-1, 0, -1):
                        if chunks[k-1][-1] > chunks[k][0]:
                            chunks[k-1] = chunks[k-1][:-1] + chunks[k][1:]
                            del chunks[k]
                    # Escape backslashes and hyphens for set difference (--).
                    # Hyphens that create ranges shouldn't be escaped.
                    stuff = '-'.join(s.replace('\\', r'\\').replace('-', r'\-')
                                     for s in chunks)
                # Escape set operations (&&, ~~ and ||).
                stuff = re.sub(r'([&~|])', r'\\\1', stuff)
                i = j+1
                if not stuff:
                    # Empty range: never match.
                    add('(?!)')
                elif stuff == '!':
                    # Negated empty range: match any character.
                    add(question_mark)
                else:
                    if stuff[0] == '!':
                        stuff = '^' + stuff[1:]
                    elif stuff[0] in ('^', '['):
                        stuff = '\\' + stuff
                    add(f'[{stuff}]')
        else:
            add(re.escape(c))
    assert i == n
    return res


def _join_translated_parts(inp, STAR):
    # Deal with STARs.
    res = []
    add = res.append
    i, n = 0, len(inp)
    # Fixed pieces at the start?
    while i < n and inp[i] is not STAR:
        add(inp[i])
        i += 1
    # Now deal with STAR fixed STAR fixed ...
    # For an interior `STAR fixed` pairing, we want to do a minimal
    # .*? match followed by `fixed`, with no possibility of backtracking.
    # Atomic groups ("(?>...)") allow us to spell that directly.
    # Note: people rely on the undocumented ability to join multiple
    # translate() results together via "|" to build large regexps matching
    # "one of many" shell patterns.
    while i < n:
        assert inp[i] is STAR
        i += 1
        if i == n:
            add(".*")
            break
        assert inp[i] is not STAR
        fixed = []
        while i < n and inp[i] is not STAR:
            fixed.append(inp[i])
            i += 1
        fixed = "".join(fixed)
        if i == n:
            add(".*")
            add(fixed)
        else:
            add(f"(?>.*?{fixed})")
    assert i == n
    return "".join(res)

def _translate(pat):
    STAR = object()

    def translate_star(h, i, n):
        return (STAR,), i

    parts = _translate_parts(pat, translate_star, '.')
    res = _join_translated_parts(parts, STAR)
    return fr'(?s:{res})\Z'


def _translate_full(pat, sep):
    SEP = re.escape(sep)
    DOT = f'[^{SEP}]'

    def translate_star(h, i, n):
        star_count = i-h
        is_segment = (h == 0 or pat[h-1] == sep) and (i == n or pat[i] == sep)
        if star_count == 1:
            if is_segment:
                return (f'{DOT}+',), i
            return (f'{DOT}*',), i
        if star_count == 2 and is_segment:
            if i == n:
                return ('.*',), i
            return (f'(.*{SEP})?',), i+1
        raise ValueError("Invalid pattern: '**' can only be an entire path component")

    parts = _translate_parts(pat, translate_star, DOT)
    res = ''.join(parts)
    return fr'(?s:{res})\Z'


